{
  "project_management_workday": {
    "summary": "Project managers (PMs) spend the vast majority of their workday on communication, coordination, and administrative tasks—often referred to as \"work about work\"—rather than the core execution of project deliverables. Their time is highly fragmented by constant context-switching between collaboration tools, documentation platforms, and project management software.",
    "time_allocation_statistics": [
      {
        "stat": "60% of time is spent on 'work about work' (coordination, status updates, searching for information)",
        "source": "Asana (via The Digital Project Manager)"
      },
      {
        "stat": "80% to 90% of time is spent on communication (meetings, email, reporting, stakeholder management)",
        "source": "Project management certification standards and industry literature"
      },
      {
        "stat": "13 hours per week are spent on email alone",
        "source": "Visual Planning"
      },
      {
        "stat": "Up to 8 hours per week are spent searching for documents, emails, and information across systems",
        "source": "McKinsey (via Pyraman)"
      }
    ],
    "most_time_consuming_tasks": [
      "Communication and coordination (meetings, chat, email)",
      "Administrative documentation and reporting",
      "Context-switching between browser tabs and disconnected applications",
      "Searching for information and managing version control"
    ],
    "mac_app_ecosystem": {
      "note": "PMs on Mac often use a mix of native apps and web-based platforms. Native apps are preferred for offline access and system integration, while web-based tools are common but often run as browser tabs or Electron wrappers.",
      "popular_apps": {
        "planning_and_gantt": [
          "OmniPlan (native macOS app for complex dependencies)",
          "Merlin Project (native macOS app)"
        ],
        "task_and_team_coordination": [
          "Asana (browser-based, no native app)",
          "Jira (browser-based, standard for IT/Engineering)",
          "Linear (native macOS app, engineering-focused)",
          "Monday.com / ClickUp (often used as browser-based or Electron wrappers)"
        ],
        "documentation_and_personal_management": [
          "Notion (native macOS app/Electron wrapper, documentation-heavy)",
          "Things 3 (native macOS app, personal task management)",
          "Fantastical (native macOS calendar)"
        ]
      },
      "caveats": "Asana does not have a native macOS desktop app in 2026 and operates entirely in the browser. Many other tools (ClickUp, Notion) utilize Electron wrappers, which can be more memory-intensive than true native apps."
    }
  }
}
